import{_ as t,c as o,o as d,b2 as r}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"路由配置","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/router.md","filePath":"docs/frontend/router.md"}'),a={name:"docs/frontend/router.md"};function c(i,e,s,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="路由配置" tabindex="-1">路由配置 <a class="header-anchor vp-link" href="#路由配置" aria-label="Permalink to &quot;路由配置&quot;">​</a></h1><h2 id="常量路由" tabindex="-1">常量路由 <a class="header-anchor vp-link" href="#常量路由" aria-label="Permalink to &quot;常量路由&quot;">​</a></h2><p>定义于 <code>src/router/index.js</code>，无需权限即可访问：</p><div class="vp-table"><table><thead><tr><th>path</th><th>说明</th></tr></thead><tbody><tr><td><code>/login</code></td><td>登录</td></tr><tr><td><code>/index</code></td><td>首页（Layout 内）</td></tr><tr><td><code>/user/profile</code></td><td>个人中心</td></tr><tr><td><code>/redirect/:path</code></td><td>刷新重定向</td></tr><tr><td><code>/401</code>、<code>/*</code></td><td>错误页</td></tr></tbody></table></div><p><strong>注意</strong>：C7 演示菜单由 Flyway 写入 <code>sys_menu</code>，登录后动态下发，<strong>不要</strong>在常量路由重复注册 <code>dev/*</code>。</p><h2 id="动态路由" tabindex="-1">动态路由 <a class="header-anchor vp-link" href="#动态路由" aria-label="Permalink to &quot;动态路由&quot;">​</a></h2><p>流程（<code>permission.js</code> + <code>store/modules/permission.js</code>）：</p><ol><li>存在 <code>Admin-Token</code> 且访问非白名单路径</li><li>若 <code>roles</code> 为空 → <code>userStore.getInfo()</code></li><li><code>permissionStore.generateRoutes()</code> → 请求 <code>GET /getRouters</code></li><li>将后端菜单转为 <code>RouteRecordRaw</code>，<code>router.addRoute</code></li><li>组件路径：<code>import.meta.glob(&#39;../../views/**/*.vue&#39;)</code> 按 <code>component</code> 字段懒加载</li></ol><p>后端菜单字段映射：</p><div class="vp-table"><table><thead><tr><th>菜单字段</th><th>路由</th></tr></thead><tbody><tr><td><code>path</code></td><td><code>route.path</code></td></tr><tr><td><code>component</code></td><td><code>views</code> 下相对路径</td></tr><tr><td><code>meta.title</code> / <code>icon</code></td><td>侧栏与 TagsView</td></tr><tr><td><code>perms</code></td><td>按钮权限（非路由）</td></tr></tbody></table></div><h2 id="白名单" tabindex="-1">白名单 <a class="header-anchor vp-link" href="#白名单" aria-label="Permalink to &quot;白名单&quot;">​</a></h2><p><code>settings.js</code> → <code>permissionWhiteList</code>：默认 <code>/login</code>、<code>/register</code>。</p><p>OAuth 授权页 <code>/oauth/authorize</code> 若需未登录访问，须在后端菜单或网关单独配置。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor vp-link" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./store.html" class="vp-link">状态管理</a></li><li><a href="./../backend/modules/permission-management.html" class="vp-link">权限管理</a></li></ul>',15)])])}const m=t(a,[["render",c]]);export{u as __pageData,m as default};
